head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil35716";

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — param.kk

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_conds();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil35716.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_kk_txt", fn: function(){ return ((dma_pageContext.get("kk") ?? "") === 1); } }, { id: "if_kk_2_txt", fn: function(){ return ((dma_pageContext.get("kk") ?? "") === 2); } }, { id: "if_kk_3_txt", fn: function(){ return ((dma_pageContext.get("kk") ?? "") === 3); } }, { id: "if_kk_4_txt", fn: function(){ return ((dma_pageContext.get("kk") ?? "") === 4); } }, { id: "txt_h115", fn: function(){ return ((dma_pageContext.get("kk") ?? "") === 1); } }, { id: "txt_h117", fn: function(){ return ((dma_pageContext.get("kk") ?? "") === 2); } }, { id: "txt_h119", fn: function(){ return ((dma_pageContext.get("kk") ?? "") === 3); } }, { id: "txt_h121", fn: function(){ return ((dma_pageContext.get("kk") ?? "") === 4); } }, { id: "if_kk_9_txt", fn: function(){ return ((dma_pageContext.get("kk") ?? "") === 1); } }, { id: "if_kk_10_txt", fn: function(){ return ((dma_pageContext.get("kk") ?? "") === 3); } }, { id: "if_kk_11_txt", fn: function(){ return ((dma_pageContext.get("kk") ?? "") === 4 || (dma_pageContext.get("kk") ?? "") === 2); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_self_onclick
 * @description 「닫기」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_self_onclick = function(e){
    try {
        $c.win.closePopup()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil35716.btn_self_onclick' }); }
};
